package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.PneumaticNetwork;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;
/** Ambient-air compressor. Redstone strength commands outlet pressure rather than acting as a binary switch. */
public class AirCompressorBlock extends Block{public AirCompressorBlock(Properties p){super(p);}@Override public MapCodec<AirCompressorBlock> codec(){return RedstoneEngineering.AIR_COMPRESSOR_CODEC.value();}public static int commandedPressure(Level l,BlockPos p){return Math.round(Math.max(0,Math.min(15,l.getBestNeighborSignal(p)))*100f/15f);}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)PneumaticNetwork.recompute(sl,p);}@Override protected void neighborChanged(BlockState s,Level l,BlockPos p,Block b,BlockPos q,boolean m){if(l instanceof ServerLevel sl)PneumaticNetwork.recompute(sl,p);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Air compressor command="+l.getBestNeighborSignal(p)+"/15 pressure="+commandedPressure(l,p)+"/100 | intake=ambient air"),true);return InteractionResult.sidedSuccess(l.isClientSide);}}
